messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Three.js 3D Animation</title>
    <style>
        body { margin:0; overflow:hidden; }
        canvas { display:block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // Simple ground and sky
        const groundGeo = new THREE.PlaneGeometry(100, 20);
        const groundMat = new THREE.MeshBasicMaterial({ color: 0xcccccc });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        scene.add(ground);

        const skyMat = new THREE.ShaderMaterial({
            vertexShader: `
                attribute vec3 position;
                uniform mat4 modelViewMatrix;
                uniform projectionMatrix;
                void main() {
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 skyColor;
                void main() {
                    gl_FragColor = vec4(skyColor, 1.0);
                }
            `,
            uniforms: { skyColor: { value: new THREE.Color(0x87ceeb) } }
        });
        const skyGeo = new THREE.PlaneGeometry(100, 20);
        const sky = new THREE.Mesh(skyGeo, skyMat);
        sky.rotation.x = -Math.PI / 2;
        scene.add(sky);

        // Red car
        const redCarGeo = new THREE.BoxGeometry(4, 2, 8);
        const redMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
        const redCar = new THREE.Mesh(redCarGeo, redMat);
        redCar.position.y = 1; // sit on ground
        scene.add(redCar);

        // Blue car
        const blueCarGeo = new THREE.BoxGeometry(4, 2, 8);
        const blueMat = new THREE.MeshBasicMaterial({ color: 0x0000ff });
        const blueCar = new THREE.Mesh(blueCarGeo, blueMat);
        blueCar.position.y = 1;
        scene.add(blueCar);

        // Finish line (simple plane)
        const finishGeo = new THREE.PlaneGeometry(100, 0.5);
        const finishMat = new THREE.MeshBasicMaterial({ color: 0xffff00, transparent: true, opacity: 0.5 });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.position.y = 1;
        finishLine.rotation.x = -Math.PI / 2;
        scene.add(finishLine);

        // Lighting
        const light = new THREE.DirectionalLight(0xffffff, 0.8);
        light.position.set(0, 20, 0);
        scene.add(light);

        // Animation loop
        const speedRed = 0.02; // units per frame
        const speedBlue = 0.015;
        let resetAfterRedFinish = false;

        function animate() {
            requestAnimationFrame(animate);

            // Move cars
            redCar.position.z += speedRed;
            blueCar.position.z += speedBlue;

            // Simple logic: blue leads, red accelerates and overtakes
            if (blueCar.position.z < redCar.position.z) {
                // blue leading
                speedBlue = 0.015;
                speedRed = 0.02;
            } else {
                // red catching up
                speedRed = 0.04; // accelerate
            }

            // Check if red car passed finish line
            if (redCar.position.z >= finishLine.position.z && !resetAfterRedFinish) {
                resetAfterRedFinish = true;
                // reset positions for loop
                redCar.position.z = -100; // far behind
                blueCar.position.z = -100;
                // reset flags
                resetAfterRedFinish = false;
            }

            renderer.render(scene, camera);
        }
        animate();

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });
    </script>
</body>
</html>
```
